import * as THREE from 'three';
export function buildWorkspaces(world,M){
 const group=new THREE.Group();group.name='occupied street frontages';const A=window.CircularCityPlan,canvas=[0xb6b58e,0x688f92,0xb2857c,0xd4c3a1].map(color=>new THREE.MeshStandardMaterial({color,roughness:1,side:THREE.DoubleSide})),metal=new THREE.MeshStandardMaterial({color:0x535a60,roughness:.8}),brick=new THREE.MeshStandardMaterial({color:0x865b4a,roughness:1}),green=new THREE.MeshStandardMaterial({color:0x4d7049,roughness:1}),pot=new THREE.MeshStandardMaterial({color:0xac7b55,roughness:1}),glow=new THREE.MeshStandardMaterial({color:0xefb96b,emissive:0xdd7133,emissiveIntensity:.7}),ivory=new THREE.MeshStandardMaterial({color:0xd8cfa5,roughness:1});
 for(const [index,w] of world.workspaces.entries()){
  const root=new THREE.Group();root.name='outdoor '+w.type;root.position.set(w.wall[0],0,w.wall[1]);root.rotation.y=-Math.atan2(w.T[1],w.T[0]);group.add(root);
  // Local negative z faces the street; every support meets the sampled ground.
  const worldAt=(x,z)=>[w.wall[0]+w.T[0]*x-w.N[0]*z,w.wall[1]+w.T[1]*x-w.N[1]*z],ground=(x,z)=>A.height(...worldAt(x,z),world)+.025;
  const box=(x,y,z,width,height,depth,material=M.wood)=>{const mesh=new THREE.Mesh(new THREE.BoxGeometry(width,height,depth),material);mesh.position.set(x,y+height/2,z);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);return mesh;};
  const beam=(a,b,width=.09,material=M.wood)=>{const from=new THREE.Vector3(...a),to=new THREE.Vector3(...b),d=to.clone().sub(from),mesh=box(0,0,0,width,d.length(),width,material);mesh.position.copy(from.add(to).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return mesh;};
  const cylinder=(x,y,z,r,h,material=pot)=>{const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r*.88,h,8),material);mesh.position.set(x,y+h/2,z);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);return mesh;};
  const cloth=canvas[index%canvas.length],top=w.roofY,front=top-.32,d=w.depth,width=w.width;
  const corners=[[-width/2,ground(-width/2,-.14),-.14],[width/2,ground(width/2,-.14),-.14],[width/2,ground(width/2,-d),-d],[-width/2,ground(-width/2,-d),-d]],floorGeo=new THREE.BufferGeometry();floorGeo.setAttribute('position',new THREE.Float32BufferAttribute([...corners[0],...corners[1],...corners[2],...corners[0],...corners[2],...corners[3]],3));floorGeo.computeVertexNormals();const floorMesh=new THREE.Mesh(floorGeo,M.road);floorMesh.receiveShadow=true;root.add(floorMesh);
  for(const side of [-1,1]){const x=side*(width/2-.08),y=ground(x,-d+.08);box(x,y,-d+.08,.12,front-y,.12);beam([x,top-.08,-.02],[x,front,-d],.12);beam([x,front-.35,-d+.05],[x,front-.06,-d+.55],.09);}beam([-width/2,top,-.02],[width/2,top,-.02],.14);beam([-width/2,front,-d],[width/2,front,-d],.13);
  const roofPositions=[],tri=(a,b,c)=>roofPositions.push(...a,...b,...c),quad=(a,b,c,e)=>{tri(a,b,c);tri(a,c,e);};const aa=[-width/2-.1,top+.08,0],bb=[width/2+.1,top+.08,0],cc=[width/2+.1,front+.08,-d-.08],dd=[-width/2-.1,front+.08,-d-.08],under=p=>[p[0],p[1]-.1,p[2]];quad(aa,bb,cc,dd);quad(under(dd),under(cc),under(bb),under(aa));for(const [a,b] of [[aa,bb],[bb,cc],[cc,dd],[dd,aa]])quad(a,under(a),under(b),b);const rg=new THREE.BufferGeometry();rg.setAttribute('position',new THREE.Float32BufferAttribute(roofPositions,3));rg.computeVertexNormals();const awning=new THREE.Mesh(rg,['forge','carpenter'].includes(w.type)?M.wood:cloth);awning.castShadow=awning.receiveShadow=true;root.add(awning);
  // The clear front of the bay remains walkable. All solid work surfaces occupy the audited bench footprint.
  const benchY=w.base+.84;box(0,benchY,-.55,width*.64,.1,.7,M.floor);for(const x of [-width*.27,width*.27])for(const z of [-.28,-.82]){const y=ground(x,z);box(x,y,z,.1,benchY-y,.1);}box(0,w.base+.3,-.55,width*.57,.08,.56);
  if(w.type==='forge'){box(-width*.16,w.base,-.55,.75,.95,.65,brick);box(-width*.16,w.base+.96,-.55,.58,.05,.48,metal);box(-width*.16,w.base+1.02,-.55,.28,.06,.2,glow);box(width*.17,benchY+.1,-.55,.37,.15,.16,metal);box(width*.16,benchY+.25,-.55,.18,.12,.27,metal);beam([width*.25,benchY+.1,-.4],[width*.34,benchY+.48,-.6],.055,M.floor);}
  else if(w.type==='carpenter'){for(let i=0;i<5;i++){box(-width*.16,w.base+.4+i*.12,-.55,width*.35,.1,.55,M.floor);box(width*.16,benchY+.1+i*.045,-.55,.9,.04,.24,M.floor);}beam([width*.16,benchY+.18,-.55],[width*.35,benchY+.45,-.55],.045,metal);}
  else if(w.type==='bookseller'){for(let i=0;i<7;i++)box(-width*.23+i*.22,benchY+.1,-.55,.15,.25+(i%3)*.07,.33,canvas[i%canvas.length]);}
  else if(w.type==='apothecary'){for(let i=0;i<6;i++){const x=-width*.23+i*.27;cylinder(x,benchY+.1,-.55,.09,.24,canvas[i%canvas.length]);cylinder(x,benchY+.34,-.55,.05,.07,M.wood);}}
  else if(w.type==='netmaker'){for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(.17+i*.025,.025,4,10),ivory);ring.rotation.x=Math.PI/2;ring.position.set(-width*.15,benchY+.14+i*.04,-.55);root.add(ring);}box(width*.18,benchY+.1,-.55,.4,.28,.35,M.floor);for(let i=0;i<5;i++)beam([-width*.24+i*.14,top-.3,-.18],[-width*.24+i*.14,top-1.15,-.18],.016,ivory);for(let i=0;i<5;i++)beam([-width*.24,top-.3-i*.18,-.18],[width*.02,top-.3-i*.18,-.18],.016,ivory);}
  else if(w.type==='weaver'){for(let i=0;i<4;i++)box(-width*.23+i*.38,benchY+.1,-.55,.3,.08+i*.025,.52,canvas[i%canvas.length]);beam([-width*.25,top-.25,-.2],[width*.25,top-.25,-.2],.06);box(0,top-1.05,-.2,width*.46,.8,.035,cloth);}
  else{for(let i=0;i<3;i++){const x=-width*.2+i*width*.2;cylinder(x,benchY+.1,-.55,.13,.2);const leaves=new THREE.Mesh(new THREE.IcosahedronGeometry(.2,0),green);leaves.position.set(x,benchY+.43,-.55);root.add(leaves);}}
  // A hanging trade marker gives the frontage a vertical landmark at pedestrian scale.
  const sx=width/2-.25;beam([sx,top-.08,-.05],[sx,top-.08,-.62],.055,metal);box(sx,top-.79,-.58,.42,.58,.07,M.wood);box(sx,top-.69,-.625,.22,.32,.02,cloth);
 }
 return group;
}
